#include <Arduino.h>
#include <Wire.h>
#include <RTClib.h>
#include <stdint.h>

RTC_DS1307 rtc;
uint32_t snapshot = 0;
bool ready = false;
char line[40];
uint8_t used = 0;
unsigned long lastByte = 0;

bool validISO(const char *s) {
  if (strlen(s) != 19) return false;
  for (uint8_t i = 0; i < 19; ++i) {
    if (i == 4 || i == 7) { if (s[i] != '-') return false; }
    else if (i == 10) { if (s[i] != 'T') return false; }
    else if (i == 13 || i == 16) { if (s[i] != ':') return false; }
    else if (s[i] < '0' || s[i] > '9') return false;
  }
  return true;
}

void processLine() {
  line[used] = '\0';
  if (ready && validISO(line)) {
    DateTime target(line);
    int64_t seconds = (int64_t)target.unixtime() - (int64_t)snapshot;
    long days = (long)(seconds / 86400LL);
    Serial.print("D-");
    Serial.println(days);
  }
  used = 0;
}

void setup() {
  Serial.begin(9600);
  Wire.begin();
  if (!rtc.begin()) return;
  snapshot = rtc.now().unixtime();
  ready = true;
}

void loop() {
  while (Serial.available() > 0) {
    char c = (char)Serial.read();
    lastByte = millis();
    if (c == '\n' || c == '\r') {
      if (used) processLine();
    } else if (used < sizeof(line) - 1) {
      line[used++] = c;
    }
  }
  if (used && (unsigned long)(millis() - lastByte) >= 20) processLine();
}
